quests[8655] = { id = 8655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenger's Greaves", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile qiraji.", objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8656] = { id = 8656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striker's Hauberk", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept this breastplate as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay its power aid you in the challenges that await you, god-slayer!", objectives = "Bring the Carapace of the Old God, 2 Idols of Life, 5 Gold Scarabs and 5 Clay Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8657] = { id = 8657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striker's Diadem", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, {name}.  I will make you a headpiece of unmatched power.", progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them.", objectives = "Bring Vek'lor's Diadem, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8658] = { id = 8658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striker's Leggings", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", progress = "Did you bring the components I require, {name}?", completion = "Yes... the worm's skin will make for an excellent protective layer.  Combined with the strongest parts from the Qiraji we've destroyed on our way here, this should make for a formidable piece of armor.  May it aid you in facing the unspeakable horrors that await inside!", objectives = "Bring the Skin of the Great Sandworm, 2 Idols of the Sun, 5 Silver Scarabs and 5 Bone Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8659] = { id = 8659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striker's Pauldrons", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies.", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of War, 5 Crystal Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8660] = { id = 8660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomcaller's Footwraps", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile Qiraji.", objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of Night, 5 Clay Scarabs and 5 Ivory Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
