quests[8826] = { id = 8826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets" }
quests[8827] = { id = 8827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winter's Presents", description = "I hear Greatfather Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.", completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Greatfather Winter hasn't forgotten about his favorite {race} {class}. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokywood Pasture's excellent products?", objectives = "Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8828] = { id = 8828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winter's Presents", description = "I hear Great-father Winter - with the generous support of Smokywood Pastures - has put presents for everyone under the tree in Orgrimmar. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.", completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Great-father Winter hasn't forgotten about his favorite {race} {class}. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokywood Pastures' excellent products?", objectives = "Speak with Great-father Winter. He is located near the Smokywood Pastures vendor area in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8829] = { id = 8829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultimate Deception", description = "The Twilight's Hammer operates through innumerable layers of secrecy and deceit.  While their actions are carried out in our world, they are planned in a place we have not yet been able to reach.\n\nWe've come to believe that the stones the Twilight's Hammer uses to summon their superiors allow for two-way transportation.  To attempt to use them in this manner, we must replicate - to every last detail - a twilight emissary's robe.\n\nGather the necessary materials and bring them to Aurel Goldleaf, {name}.", objectives = "Bring a Skin of Shadow, 3 Frayed Abomination Stitchings and 1 Twilight Cultist Robe to Aurel Goldleaf at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing XI in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
