quests[8855] = { id = 8855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thirty Signets for War Supplies" }
quests[8856] = { id = 8856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.", objectives = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Baked Salmon to Calandrath at the inn in Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8857] = { id = 8857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Colossus - Ashi", description = "I'm looking for battle hardened adventurers willing and able to get a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe in Booty Bay. No, no, I wouldn't want you to go anywhere near that thing's corpse. Just take one of my samples and make it snappy. These things are no good to him rotten!", objectives = "Take the Colossus of Ashi's Husk to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8858] = { id = 8858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Colossus - Regal", description = "There ain't nothin' I'd like more than to stuff this bug husk down Oilfist's fat face... Cept, I'm stuck here collectin' samples from that overgrown cockroach. I'll be here 'till the wee mornin' hours given the size o' that thing.\n\nTake this here sample to Oilfist fer me and do it fast, {class}. He's payin' BIG!\n\nYar, Thorium Point - it be in the Searin' Gorge.", objectives = "Take the Colossus of Regal's Husk to Overseer Oilfist in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8859] = { id = 8859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Colossus - Zora", description = "My servants were nearly killed in their efforts to recover this sample. You absolutely must hurry! Lord Maxwell Tyrosus eagerly awaits a fresh husk sample. He believes that the secrets of this Colossus could help us in the war against the Scourge!\n\nWhy are you still here!? To Light's Hope! Yes, you will be rewarded handsomely for your efforts...", objectives = "Take the Colossus of Zora's Husk to Lord Maxwell Tyrosus at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8860] = { id = 8860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Year Celebrations!", description = "Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Allison in Stormwind needs a supply of Smokywood Pastures fare to help feed all the party goers.  Can you do me a favor and deliver it?\n\nThanks, {name}!  Innkeeper Allison is in The Gilded Rose, in the Trade District of Stormwind.", progress = "Greetings!  Are you here for the party!  Or perhaps you just need to rest those weary feet of yours...", completion = "Oh, my Smokywood supplies!  Splendid!  I'll need these to feed all the people in town for the celebration!\n\nThank you, {name}.  Please take this as payment, and don't forget to drink and dance with the revelers outside!", objectives = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8861] = { id = 8861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Year Celebrations!", description = "Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show!\n\nIt should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smokywood Pastures fare to help feed all the party goers.  Can you do me a favor and deliver it?\n\nThanks, {name}!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.", progress = "Good day, {class}!  Did you come to Thunder Bluff for our celebrations?  Or are you here to rest a weary hoof between hunts?", completion = "Oh, very good!  These supplies will help feed all our people, here to celebrate the new year!\n\nI thank you, {name}.  I am in your debt.  Please, take these coins... and heed my advice - drink heartily from the kegs outside, and join our revelers in a dance of celebration!", objectives = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8862] = { id = 8862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Candle" }
quests[8863] = { id = 8863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festival Dumplings" }
quests[8864] = { id = 8864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Lunar Dresses" }
quests[8865] = { id = 8865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Lunar Pant Suits" }
quests[8866] = { id = 8866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronzebeard the Elder", objectives = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8867] = { id = 8867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunar Fireworks", description = "Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil.\n\nWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!\n\nFor a small donation you can purchase colorful rockets from our vendor. Try using some of the launchers around here, {name}.", progress = "Did you find the launchers, {name}?", completion = "Well done, {name}.\n\nNow that you're in the spirit of things, why don't you take this invitation to the festival in Moonglade.\n\nIt's quite an enjoyable celebration, if you have the time to spare.  We share food, drink, stories and of course... more fireworks!\n\nOpen the invitation while standing inside the circle of greater moonlight and you'll be transported to Moonglade.", objectives = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8868] = { id = 8868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Blessing", description = "The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake.\n\nFinally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara.  But each new year, during the festival, he stirs...\n\nGather cohorts, {name}, and summon and defeat the beast Omen.  Earn the blessing of Elune!", progress = "Omen yet stirs below below Lake Elune'ara, {name}...", completion = "Very well done, {name}.  Defeating Omen sent his spirit back to the waters of Elune'ara.  Although the beast himself is blessed by Elune and so cannot die, his anger will subside for another year.\n\nYour victory is a celebration, {name}--a celebration of the might of Omen, of you and your allies, and of the peace you have given this tragic hero of our past.", objectives = "Summon Omen, defeat him and gain Elune's Blessing. Return to Valadar Starsong in Nighthaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8869] = { id = 8869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Serenity", description = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall train you to become a hammersmith.\n\nUnderstand this: Once you have chosen the path of the hammersmith, the paths of the swordsmith and axesmith will no longer be available.", objectives = "Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8870] = { id = 8870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. ou will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", completion = "Welcome, {name}.  You're here to join us in our celebration?", objectives = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8871] = { id = 8871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8872] = { id = 8872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger at the Cenarion Enclave in Darnassus. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8873] = { id = 8873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8874] = { id = 8874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger in the entrance to the Undercity. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8875] = { id = 8875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}! The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
